#include <set>
#include <iostream>
#include <utility>

int main() {
    std::set<int> unique_s;
    std::multiset<int> multi_s;

    // 1. Unique Key (std::set) returns pair<iterator, bool>
    auto [it_u1, inserted1] = unique_s.insert(10);
    std::cout << "Insert 10 (Unique): " << (inserted1 ? "Success" : "Fail") << std::endl;

    // Attempt duplicate insertion
    auto result = unique_s.insert(10);
    std::cout << "Insert 10 (Unique): " << (result.second ? "Success" : "Fail") << std::endl;
    // result.first points to the existing element 10

    // 2. Multiple Key (std::multiset) returns iterator
    auto it_m1 = multi_s.insert(20);
    auto it_m2 = multi_s.insert(20);
    std::cout << "Multiset size: " << multi_s.size() << " (Always succeeds)" << std::endl;
}
